// Assemble the metrics table
// Current, previous week, same week last year and target per metric; deltas and flags for metrics outside their tolerance band.
return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": { "type": "string" },
    "draft": { "type": "string", "description": "The message or document text this step produced, ready to send or review" },
    "subject": { "type": "string" },
    "confidence": { "type": "number" },
    "needs_human": { "type": "boolean" },
    "reasons": { "type": "array", "items": { "type": "string" } }
  },
  "required": ["summary", "confidence", "needs_human"]
}
